from research_helpers import *
a=ev('https://www.nabors.com/for-contractors-ofs/canrig-robotics/','Current Canrig robotics catalogue confirms six named physical robotic components including exactPDH3500 and iRacker; Canrig manufacture distinct from parent association.')
