products=[]
for name,desc in [('Canrig Drill Floor Robot','Electric robot automating pipe and tool handling.'),('Canrig Robotic Roughneck','Electric tubular torque and backup tong robotic system.'),('Canrig PDH-3500','Robotic pipe-deck handling system.'),('Canrig Robotic Pipe Handler','Electric nine-degree-of-freedom tubular handling robot.'),('Canrig iRacker','Autonomous tubular racking and offline stand-building system.'),('Canrig Robotic Pipe Feeder','Electric tubular transfer robot.')]:
 products.append(p(name,desc,a,'commercial',typ='product',sector='robotics',sub='industrial_robotics',roles=['commercial_partner']))
products.append(p('Canrig RZR Rig Floor Automation Module','Integrated robotic rig-floor retrofit system.',b,'commercial',typ='product',sector='robotics',sub='industrial_robotics',roles=['commercial_partner']))
for name,desc,source in [('SmartROS','Rig operating/control software for robotic and automated drilling.',c),('SmartDRILL','Automated drilling machine-task sequencer.',d),('SmartNAV','Directional steering guidance integrated with automated rig control.',e),('SmartSLIDE','Automated directional slide-drilling controller, previouslyROCKitPilot.',f)]:
 products.append(p('Nabors '+name,desc,source,'commercial',typ='technology',sector='robotics',sub='autonomy_and_components',roles=['developer'],aliases=['ROCKit Pilot'] if name=='SmartSLIDE' else []))
products.extend([
 p('Nabors hEMS with CleanDesign battery','Integrated hybrid battery energy storage and engine-management system offered by Nabors.',g,'commercial',typ='product',sector='energy_storage',sub='batteries',roles=['commercial_partner']),
 p('Nabors PowerFLOW supercapacitor storage','Historical supercapacitor energy storage system. Current offering status unverified.',h,typ='product',sector='energy_storage',sub='supercapacitors',roles=['commercial_partner']),
 p('Nabors PACE-R801 robotic rig','Purpose-built robotic drilling demonstrator with historical field operation; series production/current deployment unverified.',i,typ='product',sector='robotics',sub='industrial_robotics',roles=['developer'],attributes={'identity_scope':'named_robotic_demonstrator_not_all_rigs'})])
co=company('Nabors Industries Ltd',products,[a,b,c,d,e,f,g,h,i],'Fourteen robotic modules/components/control technologies and storage systems entered. SmartSLIDE historicROCKitPilot identity explicit; baseROCKit not merged. CleanDesign battery partnership and historicalPowerFLOWsupercapacitor distinguished. R801 demonstrator not genericfleet SKU. Need remainingRZRdedicatedcomponents(TMQwrench,Sigma,catwalk3000,etc),SmartPLAN/ROCKit/REVit controls,currentPowerFLOWspecs,variants and partnerbattery identities. MinorityNatroninvestment alone does not imply ownership of allNatronproducts. Partial.')
(out/'batch-0178.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
